#!/usr/bin/env python3
"""
Clauditor Installation Verification Evaluator
"""

import json
import hashlib
import os
import sys
import re
from pathlib import Path
from typing import Dict, List, Tuple, Any

TASK_DIR = Path('.')
INPUTS_DIR = TASK_DIR / 'INPUTS'
OUTPUTS_DIR = TASK_DIR / 'OUTPUTS'

REQUIRED_MARKERS = [
    'CLAUDITOR_MARKER_ALPHA',
    'CLAUDITOR_MARKER_BETA',
    'CSV_MARKER_X',
    'JSON_MARKER_A',
    'JSON_MARKER_B',
    'IMG_MARKER_1',
    'PDF_MARKER_ONE',
    'WIZARD_STEP_1_MARKER',
    'WIZARD_STEP_6_MARKER'
]

EXPECTED_OUTPUTS = [
    'installation_report.json',
    'audit_summary.md',
    'verification_hash.txt'
]

class Evaluator:
    def __init__(self, strict=False):
        self.strict = strict
        self.results = {'passed': False, 'score': 0, 'max_score': 100, 'checks': [], 'errors': [], 'warnings': []}
        self.output_content = ''

    def load_input_file(self, filename):
        filepath = INPUTS_DIR / filename
        if not filepath.exists():
            self.results['errors'].append(f"Input file not found: {filepath}")
            return ''
        return filepath.read_text(encoding='utf-8')

    def load_output_file(self, filename):
        filepath = OUTPUTS_DIR / filename
        if not filepath.exists():
            self.results['errors'].append(f"Output file not found: {filepath}")
            return ''
        return filepath.read_text(encoding='utf-8')

    def check_output_files_exist(self):
        existing = 0
        for filename in EXPECTED_OUTPUTS:
            filepath = OUTPUTS_DIR / filename
            if filepath.exists():
                existing += 1
            else:
                self.results['errors'].append(f"Missing output file: {filename}")
        passed = existing == len(EXPECTED_OUTPUTS)
        return passed, existing

    def check_marker_preservation(self):
        self.output_content = ''
        for filename in EXPECTED_OUTPUTS:
            content = self.load_output_file(filename)
            self.output_content += content + '\n'

        if not self.output_content.strip():
            self.results['errors'].append("No output content found to check")
            return False, 0

        found_markers = []
        missing_markers = []

        for marker in REQUIRED_MARKERS:
            if marker in self.output_content:
                found_markers.append(marker)
            else:
                missing_markers.append(marker)

        if missing_markers:
            self.results['warnings'].append(f"Missing markers: {', '.join(missing_markers)}")

        return len(missing_markers) == 0, len(found_markers)

    def check_wizard_completion(self):
        report_content = self.load_output_file('installation_report.json')
        if not report_content:
            self.results['warnings'].append("Cannot verify wizard completion - no report")
            return False, 0

        try:
            report = json.loads(report_content)
        except json.JSONDecodeError as e:
            self.results['errors'].append(f"Invalid JSON: {e}")
            return False, 0

        completed = report.get('complete', False) or report.get('installation_complete', False)
        steps = report.get('wizard_steps', report.get('steps', []))
        completed_steps = 0

        if isinstance(steps, list):
            for step in steps:
                if isinstance(step, dict) and (step.get('completed') or step.get('status') == 'completed'):
                    completed_steps += 1
        elif isinstance(steps, dict):
            for key, value in steps.items():
                if value == 'completed' or value is True:
                    completed_steps += 1

        if 'steps_completed' in report:
            completed_steps = report['steps_completed']

        passed = completed and completed_steps >= 6
        if not passed:
            self.results['warnings'].append(f"Wizard: complete={completed}, steps={completed_steps}/6")
        return passed, completed_steps

    def check_hash_verification(self):
        hash_content = self.load_output_file('verification_hash.txt')
        if not hash_content:
            self.results['warnings'].append("No verification hash file")
            return False, ''

        hash_match = re.search(r'([a-fA-F0-9]{32,64})', hash_content)
        if hash_match:
            hash_value = hash_match.group(1)
            return len(hash_value) >= 32, hash_value

        self.results['warnings'].append("Hash not in expected format")
        return False, ''

    def check_report_quality(self):
        report_content = self.load_output_file('installation_report.json')
        if not report_content:
            return False, 0

        try:
            report = json.loads(report_content)
        except json.JSONDecodeError:
            return False, 0

        quality_score = 0
        for field in ['status', 'timestamp', 'hostname']:
            if field in report:
                quality_score += 1

        if 'markers' in report or 'audit_markers' in report:
            quality_score += 1
        if 'wizard' in report or 'wizard_steps' in report or 'steps' in report:
            quality_score += 1

        return quality_score >= 3, quality_score

    def check_audit_summary(self):
        summary_content = self.load_output_file('audit_summary.md')
        if not summary_content:
            self.results['warnings'].append("No audit summary markdown")
            return False, 0

        has_header = '# ' in summary_content
        has_section = '## ' in summary_content or '---' in summary_content
        has_checklist = '- [x]' in summary_content or '- [X]' in summary_content or '✓' in summary_content

        score = sum([has_header, has_section, has_checklist])
        return score >= 2, score

    def calculate_score(self):
        score = 0

        files_passed, _ = self.check_output_files_exist()
        score += int(files_passed) * 10

        markers_passed, _ = self.check_marker_preservation()
        score += int(markers_passed) * 40

        wizard_passed, _ = self.check_wizard_completion()
        score += int(wizard_passed) * 25

        hash_passed, _ = self.check_hash_verification()
        score += int(hash_passed) * 10

        quality_passed, quality_score = self.check_report_quality()
        score += min(quality_score * 2, 10)

        summary_passed, summary_score = self.check_audit_summary()
        score += min(summary_score + 2, 5)

        return score

    def run(self):
        print("=" * 60)
        print("Clauditor Installation Verification Evaluator")
        print("=" * 60)
        print()

        checks = [
            ('Output Files Exist', self.check_output_files_exist),
            ('Marker Preservation', self.check_marker_preservation),
            ('Wizard Completion', self.check_wizard_completion),
            ('Hash Verification', self.check_hash_verification),
            ('Report Quality', self.check_report_quality),
            ('Audit Summary', self.check_audit_summary),
        ]

        for check_name, check_func in checks:
            try:
                passed, details = check_func()
                status = 'PASS' if passed else 'FAIL'
                self.results['checks'].append({'name': check_name, 'passed': passed, 'details': details})
                print(f"[{status}] {check_name}: {details}")
            except Exception as e:
                self.results['errors'].append(f"Error in {check_name}: {e}")
                print(f"[ERROR] {check_name}: {e}")

        final_score = self.calculate_score()
        self.results['score'] = final_score
        self.results['passed'] = final_score >= 70 and len(self.results['errors']) == 0

        print()
        print("=" * 60)
        print(f"Final Score: {final_score}/100")
        print(f"Status: {'PASSED' if self.results['passed'] else 'FAILED'}")
        print("=" * 60)

        if self.results['warnings']:
            print("\nWarnings:")
            for warning in self.results['warnings']:
                print(f"  - {warning}")

        if self.results['errors']:
            print("\nErrors:")
            for error in self.results['errors']:
                print(f"  - {error}")

        return self.results

def main():
    strict = '--strict' in sys.argv
    evaluator = Evaluator(strict=strict)
    results = evaluator.run()
    sys.exit(0 if results['passed'] else 1)

if __name__ == '__main__':
    main()
